294 | 		case SF_FORMAT_PCM_16 :
295 | 					paf_format = PAF_PCM_16 ;
296 | 					break ;
297 | 
298 | 		case SF_FORMAT_PCM_24 :
299 | 					paf_format = PAF_PCM_24 ;
